cd /home/yak/fa3-cuda/reference/cursor-chats && python3 - <<'PY'
import json,re
path="69fff5d7-d194-4a1c-9ec8-de9efe54b617.jsonl"
out=[]
with open(path) as f:
    for ln,line in enumerate(f):
        line=line.strip()
        if not line: continue
        try: obj=json.loads(line)
        except: continue
        if obj.get("role")!="assistant": continue
        c=obj.get("message",{}).get("content")
        if not isinstance(c,list): continue
        for b in c:
            if isinstance(b,dict) and b.get("type")=="tool_use" and b.get("name")=="Shell":
                d=b.get("input",{}).get("description","")
                if d: out.append((ln,d))
# Early phase only: ln < 900
print("=== EARLY-PHASE (L0-900) Shell descriptions in order ===")
for ln,d in out:
    if ln<900:
        print(f"L{ln:4d} {d}")
PY

cd /home/yak/fa3-cuda/reference/cursor-chats/subagents && echo "=== per-subagent: first user prompt (task) + tool name counts ===" && for f in *.jsonl; do echo "----- $f -----"; python3 - "$f" <<'PY'
import json,sys
p=sys.argv[1]
first_user=None; tools={}
with open(p) as fh:
    for line in fh:
        line=line.strip()
        if not line: continue
        try: o=json.loads(line)
        except: continue
        c=o.get("message",{}).get("content")
        if not isinstance(c,list): continue
        if o.get("role")=="user" and first_user is None:
            for b in c:
                if isinstance(b,dict) and b.get("type")=="text":
                    first_user=b["text"]; break
        if o.get("role")=="assistant":
            for b in c:
                if isinstance(b,dict) and b.get("type")=="tool_use":
                    tools[b["name"]]=tools.get(b["name"],0)+1
if first_user:
    import re
    q=re.sub(r"<[^>]+>","",first_user).strip().replace("\n"," ")
    print("TASK:",q[:300])
print("TOOLS:",tools)
PY
done

